/* From Uiverse.io by aasisodiya - Tags: minimalist, switch */
/* The switch - the box around the slider */
.__UIV_SCOPE__ .switch {
 font-size: 1rem;
 position: relative;
 display: inline-block;
 width: 4em;
 height: 2em;
}

/* Hide default HTML checkbox */
.__UIV_SCOPE__ .switch input {
 opacity: 0;
 width: 0;
 height: 0;
}

/* The slider */
.__UIV_SCOPE__ .slider {
 position: absolute;
 cursor: pointer;
 inset: 0;
 background-color: #eee;
 transition: 0.4s;
 border-radius: 0.5em;
 box-shadow: 0 0.2em #dfd9d9;
}

.__UIV_SCOPE__ .slider:before {
 position: absolute;
 content: "";
 height: 1.5em;
 width: 1.4em;
 border-radius: 0.3em;
 left: 0.3em;
 bottom: 0.7em;
 background-color: lightsalmon;
 transition: 0.4s;
 box-shadow: 0 0.4em #bcb4b4;
}

.__UIV_SCOPE__ .slider:hover::before {
 box-shadow: 0 0.2em #bcb4b4;
 bottom: 0.5em;
}

.__UIV_SCOPE__ input:checked+.slider:before {
 transform: translateX(2em);
 background: lightgreen;
}
